(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--y-sj-prepa-ped-j2-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"y-sj-prepa-ped-j2-idesfm\",\n \"titre\": \"Préparation D.E (J) · J2 Pédiatrie IDE-SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 60,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n   \"sha256\": \"cf394cd6c30447ff59b946acd980dbf17bde1c0bb1ecbd246898dc7665837c37\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J2 (IDE-SFM)\",\n     \"slug\": \"prepa-ped-j2-idesfm\",\n     \"pages\": \"\",\n     \"count\": 60,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but des pesées est de réajuster le régime alimentaire de l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon la correction nationale de la Prépa DE (les J), l'affirmation est fausse. Le cours, lui, cite justement comme but de la pesée : « traduit l'état nutritionnel de l'enfant : réajuster un régime », en plus de suivre la courbe pondérale et de dépister une anomalie.\\n\\nSource : Licence – Soins aux enfants + Diététique (pptx 2022), diapo 156 « Pesée » ; Cours de Santé infantile L1 IDE-SFM, exercices de soins (item 9)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les fonctions de l'incubateur néonatal, le contrôle de l'humidité a peu d'intérêt par rapport à l'isolement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : l'humidité fait partie des fonctions principales de l'incubateur, au même titre que l'isolement. L'incubateur maintient le nouveau-né dans une atmosphère adaptée en température, humidité et oxygène, et assure la respiration d'un air filtré et humidifié.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Incubateur néonatal » – définition et fonctions principales\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La maîtrise de la pratique de la technique des soins ombilicaux met l'enfant à l'abri des infections comme son isolement en couveuse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : des soins ombilicaux faits avec méthode et asepsie évitent les infections du cordon (omphalite, tétanos ombilical), tout comme l'incubateur assure un isolement sur le plan infectieux.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Soins ombilicaux » (conclusion) et « Incubateur » (fonctions)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la préparation des bols de lait du nouveau-né ou du nourrisson, seules les assiettes creuses jouent un rôle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : le matériel de préparation du bol de lait comprend notamment deux assiettes plates, un bol, un gobelet, des cuillères, un couteau et des biberons stériles. Les assiettes creuses ne sont pas citées, et ce ne sont pas les seules à jouer un rôle.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Liste de matériel » (préparation du bol de lait)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En salle de naissance, les soins essentiels qui durent 90 mn font partie des soins respectueux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les soins essentiels du nouveau-né, dans le cadre du cours, sont limités aux 90 premières minutes de vie (0-1 min, 1-60 min, 60-90 min). Ils font partie des soins à donner dans le respect du couple mère-enfant (peau à peau, mise au sein précoce).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Soins essentiels aux nouveau-nés » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapos 21-27\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La préparation des laits secs en poudre maternisés respecte la proportionnalité d'une mesurette rase pour 30 ml d'eau\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : les laits secs en poudre maternisés se reconstituent à raison d'une mesurette rase (5 g) pour 30 ml d'eau bouillie tiédie.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Laits secs en poudre maternisés » et exercices de diététique\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le mot PECIMNE est un acronyme plutôt qu'un sigle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». Attention : le cours parle de « Définition du sigle PCIMNE » (Prise en Charge Intégrée des Maladies du Nouveau-né et de l'Enfant).\\n\\nSource : Cours PCIMNE 2026, diapos 8-9\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La PECIMNE veut dire Prise en charge immédiate des maladies de la mère, du nouveau-né et de l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : PCIMNE signifie Prise en Charge INTÉGRÉE des Maladies du Nouveau-né et de l'Enfant, et non « immédiate » ; la mère n'y figure pas.\\n\\nSource : Cours PCIMNE 2026, diapo 9 ; Livret de tableaux PCIMNE 0-5 ans (2021), introduction\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la pratique de la PECIMNE, les trois bandes qui permettent de classer et traiter l'enfant sont de couleur rouge, jaune et verte\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : les 3 rangées des tableaux de classification sont ROSE (grave, transfert urgent), JAUNE (traitement au centre de santé) et VERTE (soins à domicile). Il n'y a pas de rangée rouge.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), « Décider à quel groupe d'âge… » ; Cours de Pédiatrie 2 / pédiatrie cours.pdf, « Classer l'enfant »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les enfants de 2 ans à 5 ans complets ne sont pas concernés par la PECIMNE\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». Or la PCIMNE cible les enfants de 0 à 5 ans : le groupe « 2 mois à 5 ans » existe dans le livret (un enfant de 4 ans 11 mois est concerné ; seul l'enfant qui a déjà fêté ses 5 ans n'y est plus).\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), choix du tableau selon l'âge ; Cours PCIMNE 2026, diapo 11\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour les soins des orifices, il faut toujours nettoyer les oreilles de l'intérieur vers l'extérieur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : pour les oreilles, on nettoie la face interne du pavillon puis la face externe, en changeant de compresse d'une oreille à l'autre. On ne nettoie que ce que l'on voit, et jamais avec un coton-tige.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Soins des orifices – soins des oreilles »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque la mère tient l'enfant sous son bras pour le faire téter, elle adopte la position du football américain, propre aux césariennes ou aux jumeaux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : dans la position « football américain », la mère est assise et tient le nourrisson sous son bras, la tête face au sein. Elle est recommandée après une césarienne, en cas de mamelons douloureux et pour allaiter des jumeaux.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Différentes positions pour allaiter » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 281\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour le bon positionnement au sein et la bonne prise du sein, le ventre de l'enfant doit être contre celui de la mère\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : pour une bonne position, le ventre du nourrisson repose contre celui de la mère, le corps bien droit (tête, cou et dos alignés) et serré contre elle.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Technique de la bonne position » ; Pédiatrie Licence 2.pdf, « Critères d'un bon positionnement »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le premier lait de mère, le colostrum, est un véritable laxatif pour l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : parmi les caractéristiques du colostrum, le cours cite « excellent laxatif » (il aide à éliminer le méconium).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Caractéristiques du colostrum » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 267\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Comme avantage du fait de donner à téter le lait de mère à l'enfant est la prévention de l'allergie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». Pourtant le cours indique que le colostrum « prévient l'allergie et l'intolérance » et que l'allaitement aide à prévenir les maladies.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Caractéristiques du colostrum » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 266\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pré-lait provient de la nourrice d'un enfant né prématuré\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le lait pré-terme est le lait des femmes ayant accouché avant 32 SA (voire 28 SA), donc la mère (« nourrice ») d'un enfant né prématuré.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Le lait pré-terme » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 265\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour faciliter l'expulsion du placenta, il faut une mise au sein précoce\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : la succion du mamelon provoque la libération d'ocytocine par la post-hypophyse ; cette hormone fait aussi contracter l'utérus, ce qui aide au décollement et à l'expulsion du placenta.\\n\\nSource : Licence – Soins aux enfants + Diététique (pptx 2022), diapo 260 (physiologie de la lactation) — partie utérine : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À partir de 6 mois, il faut ajouter des carreaux de sucre dans le bol de lait de l'enfant du 2e âge\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : les laits maternisés (1er, 2e et 3e âge) sont déjà tous sucrés. On n'ajoute pas de carreaux de sucre au lait du 2e âge.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Laits secs en poudre maternisés »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La perte physiologique du poids chez l'enfant après la naissance intervient durant les 4 premiers jours\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai : le nouveau-né perd environ 1/10 de son poids initial pendant les 4 premiers jours (méconium, urines, perte d'eau par la peau, montée laiteuse tardive). Il récupère ce poids vers le 10e-15e jour.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Repères de gain de poids » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 157\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le carnet de santé mère et enfant compte en réalité cinq à six parties\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ». Le cours décrit QUATRE parties : 1) identité et conditions de vie des parents, 2) suivi de la grossesse, 3) accouchement, 4) suivi de l'enfant.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Carnet de santé mère-enfant » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 132\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Né normalement à 31 semaines d'aménorrhée, 1re heure, APGAR 4 puis 6 en 5 mn ; respiration plus de 60/mn avec geignement ; poids 1200 g, taille 44 cm et PC 30 cm ; plante des pieds peu striée. L'oreille garde le pli cutané.\",\n       \"text\": \"Parmi les signes suivants, une seule marque réellement la notion de prématurité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'APGAR en 1 mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La respiration rapide\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La taille de l'enfant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Poids à 1200 g\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Poids à 1200 g\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient le poids de 1200 g. L'APGAR et la respiration rapide traduisent une souffrance ou une détresse, pas l'âge gestationnel. Le petit poids (< 2500 g) est l'élément le plus évocateur parmi les choix proposés.\\n\\nSource : Pediatrie.pdf, « Signes cliniques du prématuré – aspect clinique à la naissance »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Né normalement à 31 semaines d'aménorrhée, 1re heure, APGAR 4 puis 6 en 5 mn ; respiration plus de 60/mn avec geignement ; poids 1200 g, taille 44 cm et PC 30 cm ; plante des pieds peu striée. L'oreille garde le pli cutané.\",\n       \"text\": \"De quel type de prématuré s'agit-il ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Petit prématuré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Moyen prématuré\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Grand prématuré\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Très grand prématuré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Grand prématuré\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Grand prématuré : né à 31 SA, donc entre 28 SA et 32 SA + 6 jours (28 ≤ AG < 33 SA). Le moyen prématuré correspond à 33-35 SA, le petit à 35-37 SA, le très grand à moins de 28 SA.\\n\\nSource : Pediatrie.pdf, « Le prématuré – définition et groupes » ; Cours de Pédiatrie 2 / pédiatrie cours.pdf\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Né normalement à 31 semaines d'aménorrhée, 1re heure, APGAR 4 puis 6 en 5 mn ; respiration plus de 60/mn avec geignement ; poids 1200 g, taille 44 cm et PC 30 cm ; plante des pieds peu striée. L'oreille garde le pli cutané.\",\n       \"text\": \"En plus de sa prématurité, le nouveau-né pose un problème de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Maladie des membranes hyalines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Détresse respiratoire transitoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Infection respiratoire néonatale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Syndrome d'inhalation de liquide\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Maladie des membranes hyalines\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Maladie des membranes hyalines : c'est la détresse respiratoire du prématuré. Elle est immédiate, avec geignement expiratoire, tachypnée > 60/min et cyanose, comme dans le cas. La détresse transitoire concerne plutôt les enfants à terme.\\n\\nSource : Néonatalogie.pdf, « V.5.1 Maladie des membranes hyalines » et « Tachypnée transitoire »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Né normalement à 31 semaines d'aménorrhée, 1re heure, APGAR 4 puis 6 en 5 mn ; respiration plus de 60/mn avec geignement ; poids 1200 g, taille 44 cm et PC 30 cm ; plante des pieds peu striée. L'oreille garde le pli cutané.\",\n       \"text\": \"Par quels moyens peut-on évaluer la gravité d'une détresse respiratoire chez un enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Indice de Houenou\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Indice de Silverman\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Indice de Kanawati\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Indice d'APGAR\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Indice de Silverman\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le score de Silverman cote les signes de lutte respiratoire (battement des ailes du nez, tirage, geignement, entonnoir xiphoïdien, balancement thoraco-abdominal), chacun de 0 à 2. L'APGAR évalue la vitalité à la naissance, pas la gravité de la détresse.\\n\\nSource : Néonatalogie.pdf, tableau 5 « Score de Silverman » ; Pédiatrie Licence 2.pdf, détresse respiratoire\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Né normalement à 31 semaines d'aménorrhée, 1re heure, APGAR 4 puis 6 en 5 mn ; respiration plus de 60/mn avec geignement ; poids 1200 g, taille 44 cm et PC 30 cm ; plante des pieds peu striée. L'oreille garde le pli cutané.\",\n       \"text\": \"Un indice de gravité de la détresse respiratoire chiffré à 7 est dit :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Légère\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sévère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Intense\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Modérée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Sévère\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Sévère : dans le cas clinique du cours, un score de Silverman de 7 correspond à une détresse respiratoire sévère. Le signe de gravité retenu est un Silverman supérieur à 3.\\n\\nSource : Pédiatrie Licence 2.pdf, cas « Nin-Ninkri » ; Néonatalogie.pdf, « Signes de gravité »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Né normalement à 31 semaines d'aménorrhée, 1re heure, APGAR 4 puis 6 en 5 mn ; respiration plus de 60/mn avec geignement ; poids 1200 g, taille 44 cm et PC 30 cm ; plante des pieds peu striée. L'oreille garde le pli cutané.\",\n       \"text\": \"Pour un indice d'APGAR coté à 7, on dira que le nouveau-né a\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un état modéré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un bon état\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un mauvais état\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un état moyen\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Un bon état\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un bon état : un APGAR de 7 à 10 correspond à un nouveau-né normal (état neurologique satisfaisant). De 4 à 6, il y a une souffrance cérébrale modérée ; à 3 ou moins, une souffrance sévère.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Interprétation du score d'APGAR » Remarque : Pediatrie.pdf classe « 4 à 7 » en souffrance modérée : la valeur 7 est à la limite selon les cours.\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Né normalement à 31 semaines d'aménorrhée, 1re heure, APGAR 4 puis 6 en 5 mn ; respiration plus de 60/mn avec geignement ; poids 1200 g, taille 44 cm et PC 30 cm ; plante des pieds peu striée. L'oreille garde le pli cutané.\",\n       \"text\": \"La cotation de l'APGAR est nécessaire pour la prise de décision de faire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ou ne pas faire la réanimation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De poser une sonde nasale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un massage cardiaque\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une réanimation néonatale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Ou ne pas faire la réanimation\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La cotation d'APGAR, faite à la 1re, 5e et 10e minute, sert à décider s'il faut faire ou non une réanimation : gestes simples si 4-6, réanimation systématique si ≤ 3.\\n\\nSource : Néonatalogie.pdf, « Score d'APGAR » ; Cours de Santé infantile L1 IDE-SFM, interprétation\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle de ces mesures du poids de naissance est appropriée pour désigner un gros fœtus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2320 g, Taille 51 cm, PC 32 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1320 g, Taille 35 cm, PC 27 cm\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"4320 g, Taille 53 cm, PC 37 cm\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3320 g, Taille 50 cm, PC 35 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 4320 g, Taille 53 cm, PC 37 cm\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Gros fœtus (macrosome) : poids ≥ 4000 g, avec une taille et un PC normaux ou augmentés, donc 4320 g / 53 cm / PC 37 cm. Les valeurs normales sont de 3,3 kg ± 0,5, 50 cm et 35 cm.\\n\\nSource : Pédiatrie Licence 2.pdf, « Nouveau-né de mère diabétique » ; Cours de Santé infantile L1 IDE-SFM, « Mensurations »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il est dit d'un nouveau-né qu'il est à risque s'il pèse à la naissance\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4000 g\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3320 g\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1320 g\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"2520 g\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 1320 g\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"1320 g : c'est un très petit poids de naissance (< 2500 g, et même < 1500 g), un facteur de risque majeur (hypothermie, hypoglycémie, détresse respiratoire). 2520 g, 3320 g et 4000 g ne sont pas des petits poids.\\n\\nSource : Pediatrie.pdf, « Le prématuré » ; Néonatalogie.pdf, « Prématurité »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En salle de naissance, devant un nouveau-né en pleurs avec un bras le long du corps entravant la position « W », il peut s'agir :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hématome sous-cutané gauche\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Élongation du plexus brachial\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Luxation congénitale de la hanche\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fracture de l'humérus gauche\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Élongation du plexus brachial\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Élongation (paralysie) du plexus brachial : le membre supérieur est allongé le long du corps, en adduction, ne bouge pas, la main en pronation. Elle survient après une traction forte sur l'épaule, souvent chez un macrosome.\\n\\nSource : Pédiatrie Licence 2.pdf, « Traumatisme obstétrical – cas Betchuinssa »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La durée de la prise de la température d'un enfant avec le thermomètre électronique est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 secondes à 1 minute\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 secondes à 5 minutes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"5 secondes à 10 secondes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 seconde à 2 minutes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 10 secondes à 1 minute\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le thermomètre électronique donne la mesure en quelques secondes à environ une minute (bip de fin de mesure). Le cours conseille le thermomètre électronique plutôt que celui à mercure.\\n\\nSource : Pédiatrie Licence 2.pdf, « Fièvre de l'enfant – affirmer la fièvre » ; durée : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant un nourrisson de 3 mois à 38,7 °C de fièvre, on parle de fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hyperthermie majeure\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fièvre modérée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre légère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fièvre élevée grave\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Fièvre modérée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « fièvre modérée ». Selon le degré, le cours classe : fièvre modérée 37,5-38,5 °C, fièvre élevée 38,5-40 °C, hyperthermie > 40 °C.\\n\\nSource : Pédiatrie Licence 2.pdf, « Classification de la fièvre » (Prof. Assé)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Comme signe de mauvaise tolérance de la fièvre chez le nourrisson, on note\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les extrémités froides\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des troubles conjonctivaux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un cri de cœur fort\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une conscience normale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Les extrémités froides\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les extrémités froides (avec marbrures, TRC > 3 s, cri plaintif, conscience altérée) sont des signes de mauvaise tolérance. Un cri vigoureux et une conscience normale traduisent au contraire une bonne tolérance.\\n\\nSource : Pédiatrie Licence 2.pdf, « Apprécier la tolérance de la fièvre »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'apparition des sons syllabiques doublés « pa-pa », « ma-ma », « ta-ta » apparaissent vers l'âge de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"9 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"7 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 9 mois\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Vers 9 mois, les phonèmes sont doublés (« pa-pa », « ma-ma », « ta-ta ») : ce sont les « premiers mots » pour l'entourage. Vers 6 mois, les sons syllabiques sont simplement répétés.\\n\\nSource : Pediatrie.pdf, « Développement du langage – apparition des sons syllabiques »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Face à un enfant qui présente une méningite avant 3 mois, l'agent de santé doit administrer des antibiotiques :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Amoxicilline 200 mg/kg/jour en 3 IVD, selon la stricte prescription\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ampicilline 100/kg/jour en 3 IVD + Nétilmicine 5-7 mg/kg/j 1\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Amoxicilline 200/kg/jour en 3 IVD + Nétilmicine 5-7 mg/kg/j 1 IM\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ampicilline 200 mg/kg/jour en 3 IVD selon le protocole indiqué seul\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Amoxicilline 200/kg/jour en 3 IVD + Nétilmicine 5-7 mg/kg/j 1 IM\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Avant 3 mois : ampicilline ou amoxicilline 200 mg/kg/j en 3 IVD, associée à un aminoside en 1 IM par jour. Les options sans aminoside ou avec 100 mg/kg/j sont incomplètes.\\n\\nSource : Pédiatrie Licence 2.pdf, « Méningite – modalités de l'antibiothérapie avant 3 mois » Remarque : Le cours donne l'aminoside à 3-5 mg/kg/j (et non 5-7 mg/kg/j) ; la logique de l'association est la même.\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les vomissements chroniques du nourrisson ont pour causes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Invagination de l'intestin de l'enfant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sténose hypertrophique du pylore\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Torsion d'un testicule chez le mâle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Étranglement herniaire commun\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Sténose hypertrophique du pylore\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Sténose hypertrophique du pylore : c'est une cause mécanique de vomissements CHRONIQUES (garçon premier-né, vomissements en jet 3 à 6 semaines après la naissance). L'invagination, la torsion du testicule et l'étranglement herniaire sont des causes chirurgicales de vomissements AIGUS.\\n\\nSource : Pediatrie.pdf, « Vomissements du nourrisson – causes »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la maladie hémorragique du nouveau-né, on note :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les hémorragies de causes thrombopéniques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les hémorragies dues à la manipulation du cordon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des troubles gastro-entérites chroniques\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le temps de Quick est allongé chez l'enfant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Le temps de Quick est allongé chez l'enfant\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La maladie hémorragique est due à un déficit en vitamine K1 (facteurs II, VII, IX, X), d'où un temps de Quick allongé (TP bas). Elle n'est pas d'origine thrombopénique.\\n\\nSource : Pédiatrie Licence 2.pdf, « Maladie hémorragique du nouveau-né – bilan »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'apparition du son « je » s'observe chez le nourrisson vers :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'âge de 2 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'âge de 3 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'âge de 3 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'âge de 4 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. L'âge de 3 ans\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Vers 3 ans, c'est « l'explosion grammaticale » : l'enfant construit des phrases (sujet, verbe, complément) et le « je » apparaît.\\n\\nSource : Pediatrie.pdf, « Accroissement du vocabulaire » Remarque : Les options 2 et 3 sont identiques (« 3 ans ») dans le sujet ; seule l'option 2 est cochée.\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La puberté débute chez la petite fille entre l'âge de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"14 et 15 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"12 et 13 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"13 et 14 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"10 et 11 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 10 et 11 ans\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La puberté débute chez la fille entre 10 et 11 ans, chez le garçon entre 12 et 13 ans.\\n\\nSource : Pediatrie.pdf, « Période pubertaire »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les causes infectieuses des dermatoses sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Irritation : érythème fessier\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Virales : herpès, varicelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Immunologiques : eczéma\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Toxiques : des pratiques diverses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Virales : herpès, varicelle\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Causes infectieuses des dermatoses : bactériennes (staphylocoque, streptocoque), VIRALES (herpès, varicelle), mycosiques (candida) et parasitaires (gale, poux). L'irritation (érythème fessier), l'eczéma et les causes toxiques sont non infectieuses.\\n\\nSource : Pédiatrie Licence 2.pdf, « Dermatoses du nouveau-né – étiologies »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs favorisants des dermatoses liés à la mère et à l'environnement sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'enfant de faible poids de naissance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les soins septiques chez l'enfant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La prématurité et l'hypotrophie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des moyens de défense faibles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Les soins septiques chez l'enfant\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Facteurs liés à la mère et à l'environnement : infections, maladie familiale, défaut d'hygiène, donc soins septiques. La prématurité, l'hypotrophie et la faiblesse des défenses sont des facteurs liés au nouveau-né.\\n\\nSource : Pédiatrie Licence 2.pdf, « Dermatoses – facteurs favorisants »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs favorisant l'intoxication de l'enfant sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une pneumopathie infectieuse grave du nourrisson\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le bas niveau socio-économique de la famille\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un paludisme grave ou une méningite bactérienne\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La sécurisation des produits pharmaceutiques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Le bas niveau socio-économique de la famille\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Facteurs favorisants liés aux parents et à l'environnement : faible niveau d'instruction et socio-économique, maison mal rangée, conditionnements non sécurisés, toxiques à portée de main.\\n\\nSource : Pédiatrie Licence 2.pdf, « Intoxication de l'enfant – facteurs favorisants »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La croissance du massif crânio-facial : le bregma, de forme losangique, se ferme entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"14 et 15 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"12 et 18 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"13 et 14 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"18 et 20 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 12 et 18 mois\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La fontanelle antérieure (bregma), de forme losangique, se ferme entre 12 et 18 mois. La fontanelle postérieure (lambda) ne reste palpable que les premières semaines.\\n\\nSource : Pediatrie.pdf, « Croissance des os du crâne » ; Cours de Pédiatrie 2 / pédiatrie cours.pdf\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs étiologiques de la maladie hémorragique sont constitués par :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'injection de la vitamine K1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'accouchement eutocique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La malformation rénale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La race noire surtout\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. La race noire surtout\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Facteurs favorisants de la maladie hémorragique : race noire, prématurité, J2-J3 de vie, allaitement exclusif, absence d'injection de vitamine K1, prise d'anti-vitamine K pendant la grossesse. L'injection de vitamine K1 est au contraire la prévention.\\n\\nSource : Pédiatrie Licence 2.pdf, « Maladie hémorragique – facteurs favorisants »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes désignent le niveau de développement psychomoteur de l'enfant à la naissance\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il maintient bien sa tête dans le plan du corps\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il parvient à tirer sur ses bras et peu sur ses pieds\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Attitude des membres fléchis, poings fermés\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Présente une attitude en flexion généralisée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Attitude des membres fléchis, poings fermés\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"À la naissance (0-1 mois), l'enfant est en quadri-flexion (membres supérieurs en « W », inférieurs en « M »), poings fermés, avec un réflexe de grasping. Il ne tient pas encore sa tête dans l'axe (vers 3 mois).\\n\\nSource : Cours de Pédiatrie 2 / pédiatrie cours.pdf, « Étapes du DPM » ; Pediatrie.pdf, « Tonus » Remarque : L'option 4 (« attitude en flexion généralisée ») décrit aussi la quadri-flexion ; seule l'option 3 est cochée.\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La malnutrition est un état pathologique résultant d'une inadéquation par\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La mise au sein précoce dès la naissance avec le peau à peau\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Manque de faire suivre le nourrisson à la PMI comme indiqué\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Excès en apports alimentaires par rapport aux besoins de l'organisme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Manifestation des maladies infectieuses chez le nouveau-né\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Excès en apports alimentaires par rapport aux besoins de l'organisme\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La malnutrition résulte d'une inadéquation entre les apports et les besoins de l'organisme. Elle peut être par carence (kwashiorkor, marasme) ou par EXCÈS d'apports (surpoids, obésité).\\n\\nSource : Pédiatrie Licence 2.pdf, « Malnutrition – pathogénie » ; Licence – Soins aux enfants + Diététique (pptx 2022), courbe P/T (surpoids, obésité) ; (explication hors cours du projet) pour la définition\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les ingrédients du mélange I énumérés ci-dessous, se trouve un intrus, lequel :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Farine de céréale = 2 volumes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lait en poudre entier = 6 volumes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sucre en poudre = 2 volumes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Huile végétale = 1 volume\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Farine de céréale = 2 volumes\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'intrus retenu par la correction nationale de la Prépa DE (les J) est « farine de céréale = 2 volumes ».\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plan de traitement des signes sévères de déshydratation est le :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Plan A\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Plan D\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Plan B\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Plan C\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Plan C\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Plan C : traitement de la déshydratation sévère, à l'hôpital, par perfusion (Ringer lactate…) ou SRO par sonde. Plan A : pas de déshydratation, à domicile ; plan B : signes évidents, SRO 75 ml/kg en 4 h. Il n'y a pas de plan D.\\n\\nSource : Pediatrie.pdf, « Plans de traitement A, B, C » ; Cours de Pédiatrie 2 / pédiatrie cours.pdf, tableau I\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La principale cause de détresse respiratoire chez le nouveau-né prématuré né par voie basse est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Inhalation du liquide du lait maternel lors des tétées\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Infection et les tétées peu fréquentes encore\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Trouble du langage et trouble de déglutition\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Maladie des membranes hyalines néonatales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Maladie des membranes hyalines néonatales\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Maladie des membranes hyalines : c'est « la maladie du prématuré essentiellement », due à une immaturité pulmonaire (déficit en surfactant). La prématurité est son premier facteur de risque.\\n\\nSource : Néonatalogie.pdf, « Causes médicales de détresse respiratoire – V.5.1 »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les situations à risque de détresse respiratoire du nouveau-né qui sont liées au fœtus sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Nouveau-né de mère droguée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Accouchement eutocique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Nouveau-né post-mature\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Déficit congénital ou acquis\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Dystocie dynamique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Nouveau-né post-mature\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Facteurs de risque liés à l'enfant (fœtus) : prématuré, hypotrophe, POST-TERME, malformation, souffrance cérébrale. La mère droguée, l'accouchement et la dystocie relèvent de la mère ou de l'accouchement.\\n\\nSource : Pédiatrie Licence 2.pdf, « Détresse respiratoire – facteurs de risque »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson est classé malnutri sévère quand son Z-score est compris entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"> à -3\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2 et -1\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 et -2\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"< à -1\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. > à -3\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « > à -3 ». Dans le cours, la malnutrition aiguë sévère correspond à un Z-score poids/taille INFÉRIEUR à -3 (sous la courbe -3) ; entre -3 et -2, il s'agit d'une malnutrition modérée.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), « Classer l'état nutritionnel » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 189\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les critères d'admission au centre des soins mère-kangourou sont\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Avoir des extrémités chaudes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Être un très gros fœtus de naissance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un prématuré stable\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un nouveau-né en détresse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un prématuré stable\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les soins mère kangourou commencent quand le prématuré ou le nouveau-né de petit poids est STABLE : pas de signes de danger, succion et déglutition présentes. Un nouveau-né en détresse n'est pas éligible.\\n\\nSource : Néonatalogie.pdf, « Méthode des soins mère kangourou – critères d'éligibilité »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs de gravité des maladies diarrhéiques sont les suivants sauf un, lequel :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Allaitement exclusif que certaines mères ont bien choisi de faire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faible niveau d'instruction des parents et le retard de décision\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Déficit immunitaire congénital ou acquis chez le nourrisson\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ignorance des parents pour voir les signes de déshydratation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Allaitement exclusif que certaines mères ont bien choisi de faire\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'allaitement exclusif est un facteur PROTECTEUR : le non-respect de l'allaitement exclusif jusqu'à 6 mois favorise la diarrhée. Le faible niveau d'instruction, le retard de décision, le déficit immunitaire et l'ignorance des signes de déshydratation aggravent la maladie.\\n\\nSource : Les 12 pratiques familiales essentielles (PFE), « Diarrhée – facteurs favorisants »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La photothérapie est indiquée chez le nouveau-né ictérique pour le réchauffer car la bilirubine libre est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hydrosoluble\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les deux à la fois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ni l'un ni l'autre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Liposoluble\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Liposoluble\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La bilirubine libre (non conjuguée) est liposoluble. La photothérapie, en lumière bleue, la transforme en dérivés hydrosolubles éliminés dans les urines. Le but n'est pas de réchauffer : l'hyperthermie est même un risque.\\n\\nSource : Néonatalogie.pdf, « Ictère – conduite de la photothérapie »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher seulement les bonnes réponses parmi les facteurs de déclin de l'allaitement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La montée laiteuse précoce, puis la mise au sein\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le soutien psychologique de la mère allaitante par le père\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le congé de maternité avec présence de la mère à la maison\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La promotion et la vulgarisation des laits infantiles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. La promotion et la vulgarisation des laits infantiles\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Facteurs de déclin de l'allaitement : fabrication et promotion des formules infantiles, activité professionnelle de la mère, manque de soutien psychologique, préoccupation esthétique, RETARD de la montée laiteuse. Le soutien du père et le congé de maternité favorisent au contraire l'allaitement.\\n\\nSource : Pédiatrie Licence 2.pdf, « Politiques de l'allaitement – facteurs de déclin »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__55\",\n       \"num\": \"56\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les critères d'une bonne succion sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'enfant fait le rot au cours de la tétée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une succion lente, profonde et continue\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"On entend le nouveau-né déglutir le lait maternel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La bouche est grandement ouverte et prend largement l'aréole\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. On entend le nouveau-né déglutir le lait maternel\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Critères d'une tétée (succion) efficace : succion lente et profonde entrecoupée de pauses, et on entend le bébé déglutir. « Bouche grande ouverte qui prend l'aréole » est un critère de bonne PRISE du sein.\\n\\nSource : Pédiatrie Licence 2.pdf, « Critères d'une tétée efficace » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 291\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__56\",\n       \"num\": \"57\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon les recommandations pour l'allaitement de l'enfant malade et de l'enfant en bonne santé âgé de 0 à six (6) mois, l'enfant a droit à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Deux (2) repas familiaux par jour\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Deux goûters : yaourt, œuf dur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Au moins 8 tétées en 24 heures\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Deux (2) tétées en 24 heures\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Au moins 8 tétées en 24 heures\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"De 0 à 6 mois : allaiter aussi souvent que l'enfant réclame, jour et nuit, au moins 8 fois en 24 heures, sans rien donner d'autre. Les goûters et repas familiaux ne viennent qu'après 6 mois.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans (2021), « Recommandations pour l'alimentation – de la naissance à 6 mois »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__57\",\n       \"num\": \"58\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but de la mesure du périmètre crânien est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"De dépister un spina bifida\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De dépister une microcéphalie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"D'apprécier le nombre des selles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D'augmenter le nombre de repas\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. De dépister une microcéphalie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le périmètre crânien apprécie le volume du cerveau jusqu'à 2-3 ans et permet de dépister une microcéphalie ou une hydrocéphalie. Le spina-bifida se recherche à l'examen du dos.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, « Matériel pour la mesure du PC » ; Licence – Soins aux enfants + Diététique (pptx 2022), diapo 217\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__58\",\n       \"num\": \"59\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le gavage est indiqué chez :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le nouveau-né ayant une fente labio-palatine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le nouveau-né eutrophique de mère césarisée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le nouveau-né coloré avec les extrémités cyanosées\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le nouveau-né ayant un bon réflexe de succion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le nouveau-né ayant une fente labio-palatine\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le gavage (sonde naso- ou oro-gastrique) est indiqué quand l'enfant ne peut pas téter efficacement : fente labio-palatine, prématuré sans réflexe de succion, etc. Un nouveau-né avec un bon réflexe de succion doit être mis au sein.\\n\\nSource : Néonatalogie.pdf, « Gavage – technique » ; indication fente labio-palatine : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j2-idesfm__59\",\n       \"num\": \"60\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les fonctions principales de l'incubateur sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Isolement de l'enfant de tous ses parents\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Assurer la surveillance paraclinique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Assurer la ventilation assistée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Assurer la respiration de l'air ambiant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Assurer la ventilation assistée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Fonctions de l'incubateur : neutralité thermique, respiration d'un air filtré et humidifié, isolement infectieux, surveillance CLINIQUE, et réanimation, en particulier la ventilation assistée. Isoler l'enfant de ses parents ne fait pas partie de ces fonctions.\\n\\nSource : Licence – Soins aux enfants + Diététique (pptx 2022), diapo 84 « Fonctions principales de l'incubateur » ; Cours de Santé infantile L1 IDE-SFM\",\n       \"sourceDoc\": \"Prépa D.E — J2 Pédiatrie IDE-SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J2_PEDIATRIE_IDE-SFM_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
